<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Llama4 Scout Lotte Tower Artwork</title>
    <style>
        body {
            margin: 0;
            background-color: #f0f0f0;
            font-family: Arial, sans-serif;
        }
        #canvas {
            width: 100%;
            height: 600px;
            border: 1px solid #ccc;
        }
        .controls {
            position: absolute;
            top: 10px;
            left: 10px;
            background-color: #fff;
            padding: 10px;
            border: 1px solid #ddd;
            border-radius: 5px;
            box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
        }
        .controls button {
            margin-bottom: 10px;
        }
        .controls label {
            display: block;
            margin-bottom: 10px;
        }
    </style>
</head>
<body>
    <canvas id="canvas"></canvas>
    <div class="controls">
        <label for="stage-select">Select Stage:</label>
        <select id="stage-select">
            <option value="stage1">Stage 1</option>
            <option value="stage2">Stage 2</option>
            <option value="stage3">Stage 3</option>
            <option value="stage4">Stage 4</option>
        </select>
        <button id="reset-button">Reset</button>
        <button id="home-button">Home</button>
        <label for="diagram-select">Select Diagram:</label>
        <select id="diagram-select">
            <option value="site">Site Plan</option>
            <option value="typical-floor">Typical Floor Plan</option>
            <option value="elevation">Elevation</option>
            <option value="section">Section</option>
        </select>
    </div>

    <script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
    <script>
        let camera, scene, renderer, model;

        function init() {
            const canvas = document.getElementById('canvas');
            const width = canvas.offsetWidth;
            const height = canvas.offsetHeight;

            camera = new THREE.PerspectiveCamera(45, width / height, 1, 1000);
            camera.position.set(0, 0, 500);

            scene = new THREE.Scene();

            renderer = new THREE.WebGLRenderer({
                canvas: canvas,
                antialias: true
            });
            renderer.setSize(width, height);

            // Create model
            const geometry = new THREE.BoxGeometry(100, 500, 100);
            const material = new THREE.MeshBasicMaterial({ color: 0x00ff00 });
            model = new THREE.Mesh(geometry, material);
            model.position.set(0, 250, 0);
            scene.add(model);

            // Add stages
            const stages = [];
            for (let i = 0; i < 4; i++) {
                const stageGeometry = new THREE.BoxGeometry(100, 100, 100);
                const stageMaterial = new THREE.MeshBasicMaterial({ color: 0xffffff });
                const stage = new THREE.Mesh(stageGeometry, stageMaterial);
                stage.position.set(0, i * 100, 0);
                stage.userData.label = `Stage ${i + 1}`;
                stages.push(stage);
                scene.add(stage);
            }

            // Add diagrams
            const diagrams = [];
            const sitePlanGeometry = new THREE.PlaneGeometry(500, 500);
            const sitePlanMaterial = new THREE.MeshBasicMaterial({ color: 0xffffff });
            const sitePlan = new THREE.Mesh(sitePlanGeometry, sitePlanMaterial);
            sitePlan.position.set(0, -250, 0);
            sitePlan.userData.label = 'Site Plan';
            diagrams.push(sitePlan);
            scene.add(sitePlan);

            const typicalFloorPlanGeometry = new THREE.PlaneGeometry(100, 100);
            const typicalFloorPlanMaterial = new THREE.MeshBasicMaterial({ color: 0xffffff });
            const typicalFloorPlan = new THREE.Mesh(typicalFloorPlanGeometry, typicalFloorPlanMaterial);
            typicalFloorPlan.position.set(0, 0, 0);
            typicalFloorPlan.userData.label = 'Typical Floor Plan';
            diagrams.push(typicalFloorPlan);
            scene.add(typicalFloorPlan);

            const elevationGeometry = new THREE.PlaneGeometry(100, 500);
            const elevationMaterial = new THREE.MeshBasicMaterial({ color: 0xffffff });
            const elevation = new THREE.Mesh(elevationGeometry, elevationMaterial);
            elevation.position.set(-250, 0, 0);
            elevation.userData.label = 'Elevation';
            diagrams.push(elevation);
            scene.add(elevation);

            const sectionGeometry = new THREE.PlaneGeometry(500, 100);
            const sectionMaterial = new THREE.MeshBasicMaterial({ color: 0xffffff });
            const section = new THREE.Mesh(sectionGeometry, sectionMaterial);
            section.position.set(0, 0, -250);
            section.userData.label = 'Section';
            diagrams.push(section);
            scene.add(section);

            // Add event listeners
            document.getElementById('stage-select').addEventListener('change', (e) => {
                const stage = stages.find((s) => s.userData.label === e.target.value);
                if (stage) {
                    camera.position.set(0, 0, 500);
                    camera.lookAt(stage.position);
                }
            });

            document.getElementById('reset-button').addEventListener('click', () => {
                camera.position.set(0, 0, 500);
                camera.lookAt(0, 0, 0);
            });

            document.getElementById('home-button').addEventListener('click', () => {
                camera.position.set(0, 0, 500);
                camera.lookAt(0, 0, 0);
            });

            document.getElementById('diagram-select').addEventListener('change', (e) => {
                const diagram = diagrams.find((d) => d.userData.label === e.target.value);
                if (diagram) {
                    camera.position.set(0, 0, 500);
                    camera.lookAt(diagram.position);
                }
            });

            document.addEventListener('keydown', (e) => {
                switch (e.key) {
                    case 'r':
                        camera.rotation.x += 0.1;
                        break;
                    case 'z':
                        camera.position.z += 10;
                        break;
                    case 'Z':
                        camera.position.z -= 10;
                        break;
                }
            });
        }

        function animate() {
            requestAnimationFrame(animate);
            renderer.render(scene, camera);
        }

        init();
        animate();
    </script>
</body>
</html>
